import React, { forwardRef, SyntheticEvent } from 'react';
import { useIntl } from 'react-intl';

import { _Calendar as Calendar } from './calendar/Calendar.js';
import { DatePickerOverlayBaseCSS } from './DatePickerOverlay.sty.js';
import { FocusScope } from '../../core/components/focus-scope/FocusScope.js';
import { OverlayContainer } from '../../core/components/OverlayContainer.js';
import { SharedInputPropsContext } from '../../core/contexts/SharedInputPropsContext.js';
